SELECT sum(CASE WHEN subscription_status IN ('active', 'trialing')
            THEN CASE subscription_tier
                   WHEN 'starter' THEN ${price_starter}
                   WHEN 'pro' THEN ${price_pro}
                   WHEN 'enterprise' THEN ${price_enterprise}
                   ELSE 0 END
            ELSE 0 END::numeric) AS "mrr"
FROM users u

WITH r AS (SELECT sum(CASE WHEN subscription_status IN ('active', 'trialing')
            THEN CASE subscription_tier
                   WHEN 'starter' THEN ${price_starter}
                   WHEN 'pro' THEN ${price_pro}
                   WHEN 'enterprise' THEN ${price_enterprise}
                   ELSE 0 END
            ELSE 0 END::numeric) AS mrr FROM users u),
     c AS (SELECT coalesce(sum(cost_usd), 0)::numeric AS cost FROM scans WHERE created_at > now() - interval '30 days')
SELECT (r.mrr - c.cost) / nullif(r.mrr, 0) AS "gross margin" FROM r, c
